// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Backend-agnostic verifier seam.
/// Any proof system (Groth16, WHIR, UltraHonk) implements this interface.
/// Swapping backends = deploying a new contract + calling ShieldedPool.setVerifier().
interface IProofVerifier {
    /// @param proof        Opaque proof bytes; format is implementation-specific.
    /// @param publicInputs 8-element array in the order defined by SPEC.md §4.2:
    ///                     [root, nf[0], nf[1], cm_out[0], cm_out[1],
    ///                      v_pub_in, v_pub_out, recipient]
    function verify(
        bytes calldata proof,
        uint256[] calldata publicInputs
    ) external view returns (bool);
}

