// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @notice Interface for the unified join-split shielded pool.
/// One entry point (transact) handles deposit, transfer, and withdraw.
/// Operations are distinguished by the public input values, not by function selector.
interface IShieldedPool {
    // ── Structs ───────────────────────────────────────────────────────────────

    /// @notice Public inputs to the join-split circuit.
    /// Encoding mirrors the circuit's public input vector (SPEC.md §4.2):
    /// index 0=root, 1=nf[0], 2=nf[1], 3=cm_out[0], 4=cm_out[1],
    ///       5=vPubIn, 6=vPubOut, 7=recipient
    struct PublicInputs {
        bytes32    root;
        bytes32[2] nullifiers;         // bytes32(0) = dummy / unused input slot
        bytes32[2] outputCommitments;
        uint256    vPubIn;             // ETH entering pool in wei; must equal msg.value
        uint256    vPubOut;            // ETH leaving pool in wei; 0 for deposit/transfer
        address    recipient;          // withdrawal destination; address(0) for deposit/transfer
    }

    // ── Events ────────────────────────────────────────────────────────────────

    /// @notice Emitted when a note commitment is appended to the Merkle tree.
    event NoteCommitment(uint256 indexed leafIndex, bytes32 indexed commitment);

    /// @notice Emitted once per output slot; leafIndex matches NoteCommitment.
    /// encryptedNote is always 1232 bytes: 1088 (ML-KEM-768 ct) + 12 (nonce) + 128 (AEAD ct+tag).
    event EncryptedNote(uint256 indexed leafIndex, bytes encryptedNote);

    /// @notice Emitted for each non-dummy input nullifier that is spent.
    event Nullifier(bytes32 indexed nullifier);

    /// @notice Emitted after every transact call with the updated Merkle root.
    event NewRoot(bytes32 indexed root, uint256 leafCount);

    // ── Errors ────────────────────────────────────────────────────────────────

    error PublicValueMismatch();        // msg.value != vPubIn
    error InsufficientPoolBalance();    // pool cannot cover vPubOut
    error ZeroRecipient();              // vPubOut > 0 but recipient == address(0)
    error UnknownRoot(bytes32 root);    // root not in validRoots history
    error NullifierAlreadySpent(bytes32 nullifier);
    error InvalidProof();
    error WithdrawFailed();

    // ── Functions ─────────────────────────────────────────────────────────────

    /// @notice Unified join-split entry point for deposit, transfer, and withdraw.
    /// @param proof      Opaque proof bytes forwarded to IProofVerifier.verify().
    /// @param inputs     Public inputs; validated against proof and pool state.
    /// @param encNotes   Encrypted notes, one per output slot (1232 bytes each).
    function transact(
        bytes calldata proof,
        PublicInputs calldata inputs,
        bytes[2] calldata encNotes
    ) external payable;

    /// @notice Returns true if root has ever been a valid Merkle root of the pool.
    function isValidRoot(bytes32 root) external view returns (bool);

    /// @notice Number of note commitments inserted into the Merkle tree so far.
    function leafCount() external view returns (uint256);

    /// @notice Replace the proof verifier. Owner-gated — used to swap proof backends.
    function setVerifier(address newVerifier) external;
}

